import React, { useState } from 'react';
import axios from 'axios';

export default function Sign() {
    const [firstName, setFirstName] = useState("Anirudh")
    const [lastName, setLastName] = useState("R")
    const [email, setEmail] = useState("anirudhreddy11104@gmail.com")
    const [password, setPassword] = useState("password")
    const [confirmPassword, setConfirmPassword] = useState("password")

    const handleClick = () => {
        if(password === confirmPassword) {
            axios.post("", {
                firstName:firstName,
                lastName:lastName,
                email:email,
                password:password
            })
        }
    }

    const handleFirstName = (f) => {
        setFirstName(f.target.value)
    }

    const handleLastName = (l) => {
        setLastName(l.target.value)
    }

    const handleEmail = (e) => {
        setEmail(e.target.value)
    }

    const handlePassword = (p) => {
        setPassword(p.target.value)
    }
    
    const handleConfirmPassword = (c) => {
        setConfirmPassword(c.target.value)
    }

    return (
        <div>
            First Name: <input type = "text" name = "" id = "" onChange = {handleFirstName} required /><br/>
            Last Name: <input type = "text" name = "" id = "" onChange = {handleLastName} required /><br />
            Email: <input type = "text" name = "" id = "" onChange = {handleEmail} required /><br />
            Password: <input type = "password" name = "" id = "" onChange = {handlePassword} required /><br />
            Confirm Password: <input type = "password" name = "" id = "" onChange = {handleConfirmPassword} required /><br />
            <input type = "submit" onClick={handleClick} name = "" id ="" />
            Already a user? <a href='/Login'>Login</a>
        </div>
    )

}
